Exacto. El programa completo con esa mejora:

```c
#include <stdio.h>

int main() {
    int n;
    printf("Ingresa N: ");
    scanf("%d", &n);

    if (n < 2) {
        printf("%d no es primo.\n", n);
        return 0;
    }

    int esPrimo = 1;
    for (int i = 2; i <= n / 2; i++) {
        if (n % i == 0) {
            esPrimo = 0;
            break;
        }
    }

    if (esPrimo)
        printf("%d es primo.\n", n);
    else
        printf("%d no es primo.\n", n);

    return 0;
}
```

Nota el caso especial para n < 2. El número 1 no es primo por definición.

